// 打包脚本：ESM 引擎/AI/卡池 → web/app.bundle.js（单 IIFE，挂 globalThis.OPTCG）
// 用途：file:// 直接打开（手机/电脑免 server 离线可玩）；构建后必须跑 tests/bundle.test.js 冒烟
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');

const FILES = [
  'engine/rng.js',
  'engine/state.js',
  'engine/keywords.js',
  'engine/combat.js',
  'engine/phases.js',
  'engine/legality.js',
  'engine/deck.js',
  'engine/index.js',
  'ai/actions.js',
  'ai/heuristic.js',
];

// 剥 import 行与 export 前缀（本项目模块无默认导出、无同名导出，见 bundle.test.js 守卫）
function strip(src) {
  return src
    .replace(/^import\s*\{[^}]*\}\s*from\s*[^;\n]+;?/gm, '')   // 多行 import { ... } from '...'
    .replace(/^import[^\n]*from[^\n]*$/gm, '')                  // 单行 import
    .replace(/^export \{[^}]*\}( from[^\n]*)?;?$/gm, '')
    .replace(/^export (async )?function /gm, 'function ')
    .replace(/^export const /gm, 'const ');
}

const parts = [];
parts.push('// AUTO-GENERATED by scripts/bundle.js — do not edit. Source: engine/ + ai/ + data/cards.json');
parts.push('(function (global) {');
parts.push("'use strict';");
for (const f of FILES) {
  parts.push(`// ===== ${f} =====`);
  parts.push(strip(readFileSync(join(root, f), 'utf8')));
}
parts.push(`
// ===== data/cards.json =====
const POOL = ${readFileSync(join(root, 'data/cards.json'), 'utf8')};

// ===== public API =====
global.OPTCG = {
  newGame, applyAction, cloneGame, validateDeck,
  powerOfUnit, leaderPower, usableDons, hasKeyword,
  fuse, fuseLockReason,
  listActions, createAI, evaluate, makeRng, shuffle,
  deckOf, POOL,
};
})(globalThis);
`);

writeFileSync(join(root, 'web/app.bundle.js'), parts.join('\n'), 'utf8');
console.log('bundled -> web/app.bundle.js', FILES.length + 1, 'sources');
